// Editorial explanations use the same character, class and route data as the plan.
const INVESTMENT_GUIDE=CATALOG.investmentGuide;
function ratingAnalysis(c){const g=c.growth,rs=Object.keys(routes).filter(r=>r!=='救世篇'&&firstPartHere(c,r)),primary=primaryValue(c).primaryRoutes.filter(r=>rs.includes(r));const windows=(primary.length?primary:rs).map(r=>{const t=timing(c,r);return `${routes[r]}：${t.story?'剧情入队':t.renown?'声望'+t.renown:'条件招募'}${t.chap?'，初见第'+t.chap+'章':''}`});const keys=/魔法|治疗/.test(c.role)?['mag','spd','def','res']:['str','spd','dex','def'];const strengths=keys.filter(k=>Number(g[k])>=50).map(k=>statNames[k]+g[k]+'%');const weaknesses=keys.filter(k=>Number(g[k])<=35).map(k=>statNames[k]+g[k]+'%');let limits=weaknesses.length?weaknesses.join('、')+'是培养时应优先检查的短板。':'核心成长没有明显低项，仍需核对当前伤害、攻速和生存是否达标。';if(/无法转|禁止|不能.*骑/.test(c.personalSkillEffect||''))limits+='个人技能限制骑兵 / 飞行，不能靠这两类职业补机动。';if(!c.firstPart)limits+='后期入队，没有第一部长期积累窗口。';else if(rs.length&&rs.every(r=>timing(c,r).priority!==1))limits+='各可入队线的招募或任务窗口较晚，先用开局角色过渡。';const special={c7:'优先舞者资格与生存；纯再行动不必把力量、魔力刷满，弓或魔剑只在明确需要输出时补。',c8:'值得按分工主养：蕾达补物理，凯伊补飞行；魔剑和重装按缺口补修，避免把每条线都练成同一结果。',c52:'以恢复与承伤补后期防线；速度10%不按追击核心培养，也不安排骑飞副职。',c55:'入队后直接核对法术资格与速度表现；补后期法系缺口，不倒回第一部重练。',c58:'优先完成第三部独特职责与队伍编制，不套第一部声望培养循环。'};return {basis:c.ratingReason,strength:`${strengths.length?'核心成长：'+strengths.join('、')+'。':''}${c.personalSkill}：${c.personalSkillEffect}`,window:windows.join('；')||c.joinDetails.filter(j=>j.method!=='対象外').map(j=>[j.part,j.chapter,j.note].filter(Boolean).join(' · ')).join('；')||'按剧情固定出场，核对实际入队记录。',limits:CATALOG.ratingAudit?.characters[c.id]?.limits||limits,investment:special[c.id]||INVESTMENT_GUIDE[c.rating]};}
function ratingAnalysisPanel(c){const a=ratingAnalysis(c);return `<section class="rating-analysis"><div class="rating-analysis-heading">${ratingBadge(c,false,true)}<div><h2>评级理由与投入建议</h2><p>${esc(a.basis)}</p></div></div><dl class="reason-facts">${[['优势',a.strength],['窗口',a.window],['限制',a.limits],['投入',a.investment]].map(([label,text])=>`<div><dt>${label}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl></section>`;}
function classPurpose(cl,c){const skills=cl.allowedSkills||[],b=buildPlan(c),name=cl.cn,g=cl.growth||{};if(/舞者|神乐/.test(name))return {purpose:'再行动与队伍行动效率',condition:'承担再行动职责，优先完成舞者资格与生存能力',stop:'辅助资格与生存够用就停；输出分支另按实际需求补',keys:['spd','cha','hp']};if(Number(g.def)>=25)return {purpose:'物理守线与承伤',condition:/防御|重装/.test(b.focus)?'队伍需要稳定主坦，接受低速守线定位':'主养成果已完成，但物理防御仍不能承担目标敌人攻击',stop:'达到目标战斗的承伤要求后回作战主职；不为防御长期牺牲输出成长',keys:['def','hp','str']};if(skills.includes('白魔术')&&(/白魔/.test(b.focus)||!skills.includes('黑魔术')))return {purpose:'治疗与恢复支援',condition:'队伍缺恢复覆盖，或白魔资格、关键法术仍未完成',stop:'所需法术与资格达标后停止无关武器投入',keys:['mag','res','cha']};if(skills.includes('黑魔术')&&/魔|黑魔/.test(b.focus))return {purpose:skills.includes('剑术')?'法术输出与魔法剑补位':'攻击法术与魔力成长',condition:'需要打击高物防敌人，且已准备对应魔法资格；雷电剑另检查剑术与持剑职业',stop:'核心法术与魔力够用后回主职；纯治疗无输出缺口可跳过',keys:['mag','spd','dex']};if(skills.includes('飞行术'))return {purpose:'飞行机动与突击',condition:'角色可转飞行，且已有对应骑宠与资格；凯伊线再结合友好培养',stop:'取得需要的资格与机动成果后即可；天马不能替代龙类骑宠',keys:['spd','str','res']};if(skills.includes('马术'))return {purpose:'骑乘机动与主武器作战',condition:'角色可骑乘，并已备好与职业相符的骑宠；不把机动收益当永久属性',stop:'骑乘资格与主武器达标后，按实战短板决定是否继续',keys:['str','spd','def']};if(skills.includes('黑魔术'))return {purpose:'备用法术与魔力补修',condition:'现有物理职责已完成，且确有魔法破防缺口',stop:'需要的魔法与魔力到位就回主职；没有法术用途不追加这条线',keys:['mag','spd','res']};if(skills.includes('弓术'))return {purpose:'安全远程与弓战技',condition:'承担远程职责，或确实要兼任弓手；纯法师不为弓限定熟练强练弓B',stop:'所需弓战技、装备与资格达标后停止均摊其他武器',keys:['dex','spd','str']};if(name==='勇士')return {purpose:'补力量与物理战技命中',condition:/魔法|治疗/.test(c.role)?'法术主养已完成，且装备负重确实压低攻速':'现有力量不足以完成目标伤害，或需要战技命中熟练',stop:/魔法|治疗/.test(c.role)?'补到实际负重需求就回法职；没有负重损失可跳过':'伤害 / 熟练目标到位后回作战主职，不为力量无限刷',keys:['str','hp','def']};return {purpose:skills.includes('格斗术')?'近战物理与格斗输出':'地面主武器输出与追击',condition:'需要当前武器的伤害、命中或攻速，且资格与角色适性相符',stop:'资格、目标战技和实际伤害达标就停；已有同职责成果不重复回练',keys:['str','spd','dex']};}
function careerRationale(cl,c,context={}){const primary=context.label==='主选',b=buildPlan(c),r=routeContext(c),rule=editorRule(c,r),purpose=classPurpose(cl,c),base=classBy(context.mainName),g=cl.growth||{};const n=v=>v>0?'＋'+v:String(v);let why;if(cl.col_1==='初级职业')why=initialPlan(c,b).reason;else if(primary)why=`${c.cn}在${r==='summary'?'终局整合':routes[r]+'篇'}用此职承担${purpose.purpose}。${rule?context.stage===3?rule.thirdPart:rule.reason:c.ratingReason}`;else why=`这条副职只用于${purpose.purpose}，不要求与主选一起练满。${purpose.condition}时才投入。`;const growth=purpose.keys.filter(k=>Number(g[k])!==0).slice(0,3).map(k=>statNames[k]+n(Number(g[k]))+'个百分点');const comparison=!primary&&base?purpose.keys.map(k=>({k,v:Number(g[k]||0)-Number(base.growth?.[k]||0)})).filter(x=>x.v>0).sort((a,b)=>b.v-a.v).slice(0,3):[];let gain=primary?(growth.length?'本职业成长修正：'+growth.join('、')+'。':'主要收益是武器 / 职责资格，不以额外成长为卖点。'):comparison.length?'相比主选'+base.cn+'，'+comparison.map(x=>statNames[x.k]+n(x.v)+'个百分点').join('、')+'；需要在该职业实际升级才能取得永久成长。':'相较主选，目标属性没有额外成长优势；只在确需其可用武器、战术或熟练时选择，否则跳过。';if(masteryNotes[cl.cn])gain+='熟练「'+cl.col_37+'」：'+masteryNotes[cl.cn]+'。';const losses=Object.keys(statNames).map(k=>({k,v:Number(g[k]||0)-(primary?0:Number(base?.growth?.[k]||0))})).filter(x=>x.v<0).sort((a,b)=>a.v-b.v).slice(0,3);let cost='资格：'+requirement(cl)+'；等级'+(cl.col_31||'特殊解锁')+'、声望'+(cl.col_32||'特殊')+'。'+(losses.length?(primary?'本职负修正：':'相比主选减少：')+losses.map(x=>statNames[x.k]+n(x.v)+'个百分点').join('、')+'。':'仍需投入考试资格与职业熟练时间。');const bad=new Set((c.bad||'').split(':').map(skillName)),badReq=[...cl.must,...cl.any].filter(([skill])=>bad.has(skill)).map(([skill])=>skill);if(badReq.length)cost+='资格涉及不擅长技能 '+[...new Set(badReq)].join(' / ')+'，优先利用已有熟练。';let decision=primary?'优先完成本阶段主职责；'+purpose.stop:purpose.stop+'。';if(context.stage===3)decision+='终局先看第三部解锁与当前编制，不因名称更高阶就必须替换成型职业。';if(base?.cn===cl.cn&&!primary){why='与主选为同一职业，不构成独立副职；无需重复取得资格或熟练。';decision='直接使用主选成果，跳过重复培养。';}return {why,gain,cost,decision};}
function careerReasonPanel(cl,c,context){const a=careerRationale(cl,c,context);return `<dl class="career-reasons reason-facts">${[['选择理由',a.why],['收益',a.gain],['代价',a.cost],['何时停止',a.decision]].map(([label,text])=>`<div><dt>${label}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl>`;}
